import { v4 as uuidv4 } from 'uuid';
import { QAResponse, QAHistory, Citation, Chunk, ConversationMessage } from '../shared/types';
import { PersistenceService } from './persistence-service';
import { IndexingService } from './indexing-service';
import { logger } from './logger';

const QA_HISTORY_FILE = 'qa-history.json';

/** Mock Q&A patterns keyed to document content keywords. */
const MOCK_PATTERNS: Array<{
  keywords: string[];
  answer: string;
  excerpt: string;
}> = [
  {
    keywords: ['design', 'architecture', 'pattern'],
    answer: 'The system uses a layered architecture with clear boundaries between the main process, preload scripts, and renderer. Each layer communicates through typed IPC channels, and the services layer handles business logic independently of the UI.',
    excerpt: 'The system uses a layered architecture with clear boundaries',
  },
  {
    keywords: ['import', 'document', 'file'],
    answer: 'Documents are imported by copying the source file to the local data directory. The system extracts text content and creates metadata including title, filename, size, and import timestamp. After import, documents can be indexed for search.',
    excerpt: 'Documents are imported by copying the source file',
  },
  {
    keywords: ['index', 'chunk', 'search'],
    answer: 'The indexing pipeline splits documents into chunks of approximately 500 characters at paragraph boundaries. Each chunk includes metadata like character count and word count. The index enables grounded Q&A with citations pointing to specific document sections.',
    excerpt: 'The indexing pipeline splits documents into chunks',
  },
  {
    keywords: ['retrieval', 'search', 'query'],
    answer: 'Retrieval works by matching query keywords against indexed chunks. The system ranks chunks by keyword overlap and returns the most relevant excerpts as citations alongside the generated answer.',
    excerpt: 'Retrieval works by matching query keywords against indexed chunks',
  },
  {
    keywords: ['meeting', 'notes', 'summary'],
    answer: 'The meeting summary indicates that the team discussed implementing a retrieval-augmented generation pipeline. Key decisions included using local chunk storage and citation-based verification to ensure answer accuracy.',
    excerpt: 'The team discussed implementing a retrieval-augmented generation pipeline',
  },
];

/** Words too common to signal relevance; ignored during keyword matching. */
const STOPWORDS = new Set([
  'the', 'and', 'for', 'are', 'was', 'were', 'what', 'when', 'where', 'which', 'who', 'why', 'how',
  'does', 'did', 'can', 'could', 'would', 'should', 'about', 'that', 'this', 'these', 'those', 'then',
  'than', 'with', 'from', 'into', 'its', 'it\'s', 'more', 'tell', 'there', 'their', 'they', 'them',
  'you', 'your', 'have', 'has', 'had', 'not', 'any', 'all', 'also', 'some', 'work', 'works',
]);

export class QaService {
  private persistence: PersistenceService;
  private indexingService: IndexingService;
  private log = logger.forService('QaService');

  constructor(persistence: PersistenceService, indexingService?: IndexingService) {
    this.persistence = persistence;
    this.indexingService = indexingService ?? new IndexingService(persistence);
    this.log.info('QaService initialized');
  }

  /**
   * Ask a question and get a grounded answer with citations.
   *
   * Multi-turn behaviour: if the question alone matches no indexed chunk (typical
   * for follow-ups such as "what about its chunks?"), retrieval is retried with
   * the previous question added as context.
   */
  async ask(question: string): Promise<QAResponse> {
    const trimmed = question.trim();
    if (!trimmed) {
      throw new Error('Question must not be empty');
    }
    const askedAt = new Date().toISOString();
    this.log.info('Processing question', { question: trimmed });

    // Simulate processing delay
    await new Promise(resolve => setTimeout(resolve, 100 + Math.random() * 400));

    const chunks = this.indexingService.getAllChunks();
    this.log.info('Retrieving from chunks', { totalChunks: chunks.length });

    let retrievalText = trimmed;
    let relevant = this.findRelevantChunks(trimmed, chunks);
    let usedConversationContext = false;

    const history = this.getHistory();
    const previous = history[history.length - 1];
    if (relevant.length === 0 && previous && chunks.length > 0) {
      const withContext = `${previous.question} ${trimmed}`;
      const contextual = this.findRelevantChunks(withContext, chunks);
      if (contextual.length > 0) {
        relevant = contextual;
        retrievalText = withContext;
        usedConversationContext = true;
      }
    }

    this.log.info('Keyword matching results', {
      relevantChunks: relevant.length,
      usedConversationContext,
    });

    // Get document metadata for citations
    const docs = this.persistence.readJson<Array<{ id: string; title: string }>>('documents-meta.json') ?? [];
    const citations: Citation[] = relevant.map(chunk => ({
      documentId: chunk.documentId,
      documentTitle: docs.find(d => d.id === chunk.documentId)?.title ?? 'Unknown Document',
      chunkIndex: chunk.index,
      excerpt: chunk.content.substring(0, 200),
    }));

    // Generate answer from mock patterns or use fallback
    const answer = this.generateAnswer(retrievalText, citations);

    const response: QAResponse = {
      answer,
      citations,
      confidence: citations.length > 0 ? 0.85 : 0.3,
      timestamp: new Date().toISOString(),
      usedConversationContext,
    };

    this.log.info('Q&A response generated', {
      confidence: response.confidence,
      citationCount: citations.length,
      answerLength: answer.length,
    });

    this.saveToHistory({ id: uuidv4(), question: trimmed, askedAt, response });

    return response;
  }

  /** Get the Q&A history, oldest first. Entries always carry an `id` and `askedAt`. */
  getHistory(): QAHistory[] {
    let raw: QAHistory[] | null;
    try {
      raw = this.persistence.readJson<QAHistory[]>(QA_HISTORY_FILE);
    } catch (err) {
      this.log.error('Q&A history file is unreadable; treating as empty', { error: String(err) });
      return [];
    }
    if (!Array.isArray(raw)) return [];
    return raw.map((entry, i) => ({
      ...entry,
      id: entry.id ?? `legacy-${i}`,
      askedAt: entry.askedAt ?? entry.response.timestamp,
    }));
  }

  /** Get the history as an ordered list of user/assistant messages for the conversation view. */
  getConversation(): ConversationMessage[] {
    const history = this.getHistory();
    const messages = history.flatMap((entry): ConversationMessage[] => {
      const turnId = entry.id as string;
      return [
        {
          id: `${turnId}:q`,
          turnId,
          role: 'user',
          content: entry.question,
          timestamp: entry.askedAt as string,
        },
        {
          id: `${turnId}:a`,
          turnId,
          role: 'assistant',
          content: entry.response.answer,
          timestamp: entry.response.timestamp,
          citations: entry.response.citations ?? [],
          confidence: entry.response.confidence,
          usedConversationContext: entry.response.usedConversationContext ?? false,
        },
      ];
    });
    this.log.info('Conversation built', { turns: history.length, messages: messages.length });
    return messages;
  }

  /** Clear the Q&A history. */
  clearHistory(): void {
    this.persistence.writeJson(QA_HISTORY_FILE, []);
    this.log.info('Q&A history cleared');
  }

  /** Rank chunks by keyword overlap with the text and return the top 2 matches. */
  private findRelevantChunks(text: string, chunks: Chunk[]): Chunk[] {
    const words = text
      .toLowerCase()
      .split(/\s+/)
      .map(w => w.replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, ''))
      .filter(w => w.length > 2 && !STOPWORDS.has(w));
    return chunks
      .map(chunk => {
        const contentLower = chunk.content.toLowerCase();
        const score = words.reduce((acc, word) => acc + (contentLower.includes(word) ? 1 : 0), 0);
        return { chunk, score };
      })
      .filter(s => s.score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, 2)
      .map(s => s.chunk);
  }

  private generateAnswer(question: string, citations: Citation[]): string {
    // Match against mock patterns
    const questionLower = question.toLowerCase();
    for (const pattern of MOCK_PATTERNS) {
      if (pattern.keywords.some(kw => questionLower.includes(kw))) {
        if (citations.length > 0) {
          return `${pattern.answer} Based on the document "${citations[0].documentTitle}", ${citations[0].excerpt.substring(0, 100)}.`;
        }
        return pattern.answer;
      }
    }

    // Fallback answer
    if (citations.length > 0) {
      return `Based on the available documents, the most relevant information comes from "${citations[0].documentTitle}": ${citations[0].excerpt.substring(0, 150)}. However, a more specific answer would require additional context.`;
    }

    return 'No relevant documents have been indexed yet. Please import and index documents before asking questions.';
  }

  private saveToHistory(entry: QAHistory): void {
    const history = this.getHistory();
    history.push(entry);
    this.persistence.writeJson(QA_HISTORY_FILE, history);
    this.log.info('Question saved to history', { historyLength: history.length });
  }
}
import { useState, useCallback, useEffect } from 'react';
import { DocumentList } from './components/DocumentList';
import { QuestionPanel } from './components/QuestionPanel';
import { DocumentDetail } from './components/DocumentDetail';
import { ConversationHistory } from './components/ConversationHistory';
import { StatusBar } from './components/StatusBar';
import { Document, AppStatus, ConversationMessage } from '../shared/types';
import { describeError } from './utils/format';
import type { FailedQuestion, PendingQuestion, TurnFocusRequest } from './components/QuestionPanel';


export function App() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [selectedDoc, setSelectedDoc] = useState<Document | null>(null);
  const [appStatus, setAppStatus] = useState<AppStatus>({
    documentsLoaded: 0,
    indexStatus: 'idle',
    lastActivity: '',
  });
  const [messages, setMessages] = useState<ConversationMessage[]>([]);
  const [historyLoadError, setHistoryLoadError] = useState<string | null>(null);
  const [pending, setPending] = useState<PendingQuestion | null>(null);
  const [failed, setFailed] = useState<FailedQuestion | null>(null);
  const [focusRequest, setFocusRequest] = useState<TurnFocusRequest | null>(null);
  const [activeTab, setActiveTab] = useState<'documents' | 'conversation'>('documents');

  const refreshDocuments = useCallback(async () => {
    try {
      const docs = await window.knowledgeBase.documents.list();
      setDocuments(docs);
      const status = await window.knowledgeBase.indexing.status();
      setAppStatus(status);
    } catch (err) {
      console.error('Failed to refresh documents:', err);
    }
  }, []);

  const refreshHistory = useCallback(async () => {
    try {
      const conversation = await window.knowledgeBase.conversation.get();
      setMessages(conversation);
      setHistoryLoadError(null);
    } catch (err) {
      console.error('Failed to refresh conversation history:', err);
      setHistoryLoadError(describeError(err));
    }
  }, []);

  useEffect(() => {
    refreshDocuments();
    refreshHistory();
  }, [refreshDocuments, refreshHistory]);

  const handleImport = useCallback(async () => {
    console.log('Import triggered - use window.knowledgeBase.documents.import(filePath)');
  }, []);

  const handleSelectDocument = useCallback((doc: Document) => {
    setSelectedDoc(doc);
  }, []);

  const handleAskQuestion = useCallback(async (question: string) => {
    const askedAt = new Date().toISOString();
    setFailed(null);
    setPending({ question, askedAt });
    try {
      await window.knowledgeBase.qa.ask(question);
      await refreshHistory();
    } catch (err) {
      console.error('Q&A failed:', err);
      setFailed({ question, askedAt, error: describeError(err) });
    } finally {
      setPending(null);
    }
  }, [refreshHistory]);

  const handleRetry = useCallback(() => {
    if (failed) handleAskQuestion(failed.question);
  }, [failed, handleAskQuestion]);

  const handleClearHistory = useCallback(async () => {
    try {
      await window.knowledgeBase.qa.clearHistory();
    } catch (err) {
      console.error('Failed to clear history:', err);
    }
    await refreshHistory();
  }, [refreshHistory]);

  const isDocumentAvailable = useCallback(
    (documentId: string) => documents.some(d => d.id === documentId),
    [documents],
  );

  const handleOpenDocument = useCallback((documentId: string) => {
    const doc = documents.find(d => d.id === documentId);
    if (doc) setSelectedDoc(doc);
  }, [documents]);

  const handleSelectTurn = useCallback((turnId: string) => {
    setFocusRequest(prev => ({ turnId, nonce: (prev?.nonce ?? 0) + 1 }));
  }, []);

  const turnCount = messages.filter(m => m.role === 'user').length;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <header style={{
        padding: '12px 20px',
        background: '#16213e',
        borderBottom: '1px solid #0f3460',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <h1 style={{ fontSize: '18px', fontWeight: 600 }}>Knowledge Base</h1>
        <button
          onClick={refreshDocuments}
          style={{
            padding: '6px 14px',
            background: '#0f3460',
            color: '#e0e0e0',
            border: '1px solid #1a1a4e',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '13px',
          }}
        >
          Refresh
        </button>
      </header>

      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        {/* Left panel: Document list + Conversation tabs */}
        <div style={{
          width: '280px',
          borderRight: '1px solid #0f3460',
          display: 'flex',
          flexDirection: 'column',
          background: '#16213e',
        }}>
          <div style={{
            display: 'flex',
            borderBottom: '1px solid #0f3460',
          }}>
            <button
              type="button"
              aria-pressed={activeTab === 'documents'}
              onClick={() => setActiveTab('documents')}
              style={{
                flex: 1,
                padding: '8px',
                background: activeTab === 'documents' ? '#0f3460' : 'transparent',
                color: activeTab === 'documents' ? '#e0e0e0' : '#666',
                border: 'none',
                borderBottom: activeTab === 'documents' ? '2px solid #533483' : '2px solid transparent',
                cursor: 'pointer',
                fontSize: '12px',
                fontWeight: 500,
              }}
            >
              Documents ({documents.length})
            </button>
            <button
              type="button"
              aria-pressed={activeTab === 'conversation'}
              onClick={() => setActiveTab('conversation')}
              style={{
                flex: 1,
                padding: '8px',
                background: activeTab === 'conversation' ? '#0f3460' : 'transparent',
                color: activeTab === 'conversation' ? '#e0e0e0' : '#666',
                border: 'none',
                borderBottom: activeTab === 'conversation' ? '2px solid #533483' : '2px solid transparent',
                cursor: 'pointer',
                fontSize: '12px',
                fontWeight: 500,
              }}
            >
              History ({turnCount})
            </button>
          </div>
          {activeTab === 'documents' ? (
            <>
              <div style={{
                padding: '6px 16px',
                display: 'flex',
                justifyContent: 'flex-end',
              }}>
                <button
                  onClick={handleImport}
                  style={{
                    padding: '4px 10px',
                    background: '#533483',
                    color: '#fff',
                    border: 'none',
                    borderRadius: '3px',
                    cursor: 'pointer',
                    fontSize: '12px',
                  }}
                >
                  + Import
                </button>
              </div>
              <DocumentList
                documents={documents}
                onSelect={handleSelectDocument}
                selectedId={selectedDoc?.id ?? null}
              />
            </>
          ) : (
            <ConversationHistory messages={messages} onSelectTurn={handleSelectTurn} />
          )}
        </div>

        {/* Right panel: selected document (optional) above the conversation */}
        <main style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
          {selectedDoc && (
            <section
              aria-label="Selected document"
              style={{ position: 'relative', maxHeight: '45%', overflow: 'auto', padding: '20px', flexShrink: 0 }}
            >
              <button
                type="button"
                onClick={() => setSelectedDoc(null)}
                aria-label="Close document"
                style={{
                  position: 'absolute',
                  top: '12px',
                  right: '16px',
                  padding: '2px 8px',
                  background: 'transparent',
                  color: '#c0c0dd',
                  border: '1px solid #2a2a5e',
                  borderRadius: '3px',
                  cursor: 'pointer',
                  fontSize: '12px',
                }}
              >
                Close
              </button>
              <DocumentDetail document={selectedDoc} />
            </section>
          )}

          <QuestionPanel
            messages={messages}
            pending={pending}
            failed={failed}
            loadError={historyLoadError}
            focusRequest={focusRequest}
            onAsk={handleAskQuestion}
            onRetry={handleRetry}
            onDismissError={() => setFailed(null)}
            onReloadHistory={refreshHistory}
            onClearHistory={handleClearHistory}
            isDocumentAvailable={isDocumentAvailable}
            onOpenDocument={handleOpenDocument}
          />
        </main>
      </div>

      <StatusBar status={appStatus} />
    </div>
  );
}
import { contextBridge, ipcRenderer } from 'electron';
import type { IPC_CHANNELS as SharedChannels } from '../shared/types';

/*
 * Sandboxed preload scripts cannot require() local modules, so a runtime import
 * of ../shared/types fails and the bridge is never exposed. The channel map is
 * therefore repeated here, but typed against the shared definition: the
 * type-only import is erased at runtime and tsc rejects any drift.
 */
const IPC_CHANNELS: typeof SharedChannels = {
  LIST_DOCUMENTS: 'documents:list',
  IMPORT_DOCUMENT: 'documents:import',
  GET_DOCUMENT: 'documents:get',
  DELETE_DOCUMENT: 'documents:delete',
  START_INDEXING: 'indexing:start',
  GET_INDEXING_STATUS: 'indexing:status',
  GET_CHUNKS: 'indexing:chunks',
  ASK_QUESTION: 'qa:ask',
  GET_HISTORY: 'qa:history',
  CLEAR_HISTORY: 'qa:clear-history',
  GET_CONVERSATION: 'conversation:get',
  WRITE_CLIPBOARD: 'clipboard:write-text',
  GET_STATUS: 'app:status',
};

const api = {
  documents: {
    list: () => ipcRenderer.invoke(IPC_CHANNELS.LIST_DOCUMENTS),
    import: (filePath: string) => ipcRenderer.invoke(IPC_CHANNELS.IMPORT_DOCUMENT, filePath),
    get: (id: string) => ipcRenderer.invoke(IPC_CHANNELS.GET_DOCUMENT, id),
    delete: (id: string) => ipcRenderer.invoke(IPC_CHANNELS.DELETE_DOCUMENT, id),
  },
  indexing: {
    start: (documentId?: string) => ipcRenderer.invoke(IPC_CHANNELS.START_INDEXING, documentId),
    status: () => ipcRenderer.invoke(IPC_CHANNELS.GET_INDEXING_STATUS),
    chunks: (documentId: string) => ipcRenderer.invoke(IPC_CHANNELS.GET_CHUNKS, documentId),
  },
  qa: {
    ask: (question: string) => ipcRenderer.invoke(IPC_CHANNELS.ASK_QUESTION, question),
    history: () => ipcRenderer.invoke(IPC_CHANNELS.GET_HISTORY),
    clearHistory: () => ipcRenderer.invoke(IPC_CHANNELS.CLEAR_HISTORY),
  },
  conversation: {
    get: () => ipcRenderer.invoke(IPC_CHANNELS.GET_CONVERSATION),
  },
  clipboard: {
    writeText: (text: string) => ipcRenderer.invoke(IPC_CHANNELS.WRITE_CLIPBOARD, text),
  },
};

contextBridge.exposeInMainWorld('knowledgeBase', api);
import { IpcMain, clipboard } from 'electron';
import { DocumentService } from '../services/document-service';
import { IndexingService } from '../services/indexing-service';
import { QaService } from '../services/qa-service';
import { IPC_CHANNELS } from '../shared/types';
import { logger } from '../services/logger';

export interface Services {
  documentService: DocumentService;
  indexingService: IndexingService;
  qaService: QaService;
}

export function registerIpcHandlers(ipcMain: IpcMain, services: Services) {
  const { documentService, indexingService, qaService } = services;
  const log = logger.forService('IPC');

  // Document operations
  ipcMain.handle(IPC_CHANNELS.LIST_DOCUMENTS, async () => {
    log.info('LIST_DOCUMENTS');
    return documentService.listDocuments();
  });

  ipcMain.handle(IPC_CHANNELS.IMPORT_DOCUMENT, async (_event, filePath: string) => {
    log.info('IMPORT_DOCUMENT', { filePath });
    try {
      const doc = documentService.importDocument(filePath);
      log.info('Document imported', { id: doc.id, title: doc.title, size: doc.size });
      return doc;
    } catch (err) {
      log.error('Document import failed', { filePath, error: String(err) });
      throw err;
    }
  });

  ipcMain.handle(IPC_CHANNELS.GET_DOCUMENT, async (_event, id: string) => {
    log.info('GET_DOCUMENT', { id });
    return documentService.getDocument(id);
  });

  ipcMain.handle(IPC_CHANNELS.DELETE_DOCUMENT, async (_event, id: string) => {
    log.info('DELETE_DOCUMENT', { id });
    return documentService.deleteDocument(id);
  });

  // Indexing
  ipcMain.handle(IPC_CHANNELS.START_INDEXING, async (_event, documentId?: string) => {
    log.info('START_INDEXING', { documentId: documentId ?? 'all' });
    try {
      const status = await indexingService.startIndexing(documentId);
      log.info('Indexing complete', { status: status.status, indexed: status.currentIndexed, total: status.totalDocuments });
      return status;
    } catch (err) {
      log.error('Indexing failed', { documentId, error: String(err) });
      throw err;
    }
  });

  ipcMain.handle(IPC_CHANNELS.GET_INDEXING_STATUS, async () => {
    return indexingService.getStatus();
  });

  ipcMain.handle(IPC_CHANNELS.GET_CHUNKS, async (_event, documentId: string) => {
    log.info('GET_CHUNKS', { documentId });
    return indexingService.getChunksForDocument(documentId);
  });

  // Q&A
  ipcMain.handle(IPC_CHANNELS.ASK_QUESTION, async (_event, question: string) => {
    log.info('ASK_QUESTION', { question });
    try {
      const response = await qaService.ask(question);
      log.info('Q&A response', {
        confidence: response.confidence,
        citationCount: response.citations.length,
      });
      return response;
    } catch (err) {
      log.error('Q&A failed', { question, error: String(err) });
      throw err;
    }
  });

  ipcMain.handle(IPC_CHANNELS.GET_HISTORY, async () => {
    log.info('GET_HISTORY');
    return qaService.getHistory();
  });

  ipcMain.handle(IPC_CHANNELS.CLEAR_HISTORY, async () => {
    log.info('CLEAR_HISTORY');
    qaService.clearHistory();
  });

  // Conversation
  ipcMain.handle(IPC_CHANNELS.GET_CONVERSATION, async () => {
    log.info('GET_CONVERSATION');
    return qaService.getConversation();
  });

  // Clipboard
  ipcMain.handle(IPC_CHANNELS.WRITE_CLIPBOARD, async (_event, text: string) => {
    log.info('WRITE_CLIPBOARD', { length: typeof text === 'string' ? text.length : 0 });
    if (typeof text !== 'string') throw new Error('Clipboard text must be a string');
    clipboard.writeText(text);
  });
}
/** Cross-boundary type definitions shared between main, preload, and renderer. */

export interface Document {
  id: string;
  title: string;
  filename: string;
  importedAt: string;
  size: number;
  status: 'imported' | 'indexing' | 'indexed' | 'error';
  chunks?: number;
}

export interface Chunk {
  id: string;
  documentId: string;
  content: string;
  index: number;
  metadata: Record<string, string>;
}

export interface Citation {
  documentId: string;
  documentTitle: string;
  chunkIndex: number;
  excerpt: string;
}

export interface QAResponse {
  answer: string;
  citations: Citation[];
  confidence: number;
  timestamp: string;
  /** True when the previous question was used to resolve a follow-up question. */
  usedConversationContext?: boolean;
}

export interface QAHistory {
  /** Stable id for the exchange. Optional because history written before ids existed lacks it. */
  id?: string;
  question: string;
  /** When the question was asked. Older entries only have `response.timestamp`. */
  askedAt?: string;
  response: QAResponse;
}

/** One message in the conversation view; each Q&A exchange yields a user and an assistant message. */
export interface ConversationMessage {
  id: string;
  /** Id of the exchange this message belongs to (shared by the question and its answer). */
  turnId: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: string;
  citations?: Citation[];
  confidence?: number;
  usedConversationContext?: boolean;
}

export interface AppStatus {
  documentsLoaded: number;
  indexStatus: 'idle' | 'indexing' | 'ready' | 'error';
  lastActivity: string;
}

/** IPC channel names — single source of truth. */
export const IPC_CHANNELS = {
  // Document operations
  LIST_DOCUMENTS: 'documents:list',
  IMPORT_DOCUMENT: 'documents:import',
  GET_DOCUMENT: 'documents:get',
  DELETE_DOCUMENT: 'documents:delete',

  // Indexing
  START_INDEXING: 'indexing:start',
  GET_INDEXING_STATUS: 'indexing:status',
  GET_CHUNKS: 'indexing:chunks',

  // Q&A
  ASK_QUESTION: 'qa:ask',
  GET_HISTORY: 'qa:history',
  CLEAR_HISTORY: 'qa:clear-history',

  // Conversation
  GET_CONVERSATION: 'conversation:get',

