import { useEffect, useRef, useState, type CSSProperties } from 'react';
import { ConversationMessage } from '../../shared/types';
import { CitationList } from './CitationList';
import { formatFullTimestamp, formatTimestamp } from '../utils/format';

export interface PendingQuestion {
  question: string;
  askedAt: string;
}

export interface FailedQuestion extends PendingQuestion {
  error: string;
}

export interface TurnFocusRequest {
  turnId: string;
  /** Changes on every request so selecting the same turn twice still scrolls. */
  nonce: number;
}

interface Props {
  messages: ConversationMessage[];
  pending: PendingQuestion | null;
  failed: FailedQuestion | null;
  loadError: string | null;
  focusRequest: TurnFocusRequest | null;
  onAsk: (question: string) => void;
  onRetry: () => void;
  onDismissError: () => void;
  onReloadHistory: () => void;
  onClearHistory: () => Promise<void>;
  isDocumentAvailable: (documentId: string) => boolean;
  onOpenDocument: (documentId: string) => void;
}

const EXAMPLE_QUESTIONS = [
  'How does the indexing pipeline work?',
  'What was decided in the meeting?',
  'How are documents imported?',
];

const smallButton: CSSProperties = {
  padding: '3px 10px',
  background: 'transparent',
  color: '#c0c0dd',
  border: '1px solid #2a2a5e',
  borderRadius: '3px',
  cursor: 'pointer',
  fontSize: '11px',
};

const metaText: CSSProperties = { fontSize: '11px', color: '#a8a8c8' };

function Timestamp({ iso }: { iso: string }) {
  return (
    <time dateTime={iso} title={formatFullTimestamp(iso)} style={metaText}>
      {formatTimestamp(iso)}
    </time>
  );
}

function CopyButton({ text }: { text: string }) {
  const [state, setState] = useState<'idle' | 'copied' | 'failed'>('idle');

  useEffect(() => {
    if (state === 'idle') return;
    const t = setTimeout(() => setState('idle'), 2000);
    return () => clearTimeout(t);
  }, [state]);

  const copy = async () => {
    try {
      await window.knowledgeBase.clipboard.writeText(text);
      setState('copied');
    } catch {
      setState('failed');
    }
  };

  return (
    <button type="button" onClick={copy} style={smallButton} aria-label="Copy answer">
      {state === 'copied' ? 'Copied' : state === 'failed' ? 'Copy failed' : 'Copy'}
      <span className="sr-only" aria-live="polite">
        {state === 'copied' ? 'Answer copied to clipboard' : state === 'failed' ? 'Could not copy answer' : ''}
      </span>
    </button>
  );
}

function bubble(role: 'user' | 'assistant', highlighted: boolean): CSSProperties {
  const isUser = role === 'user';
  return {
    alignSelf: isUser ? 'flex-end' : 'flex-start',
    maxWidth: isUser ? '75%' : '85%',
    minWidth: 0,
    padding: '10px 14px',
    borderRadius: isUser ? '10px 10px 2px 10px' : '10px 10px 10px 2px',
    background: isUser ? '#533483' : '#1a1a3e',
    border: `1px solid ${highlighted ? '#9d7fe0' : isUser ? '#533483' : '#0f3460'}`,
    boxShadow: highlighted ? '0 0 0 2px rgba(157,127,224,0.35)' : 'none',
    transition: 'box-shadow 0.3s, border-color 0.3s',
  };
}

const messageText: CSSProperties = {
  fontSize: '14px',
  lineHeight: 1.6,
  whiteSpace: 'pre-wrap',
  overflowWrap: 'anywhere',
};

/** Multi-turn Q&A: the conversation thread plus the question composer. */
export function QuestionPanel({
  messages,
  pending,
  failed,
  loadError,
  focusRequest,
  onAsk,
  onRetry,
  onDismissError,
  onReloadHistory,
  onClearHistory,
  isDocumentAvailable,
  onOpenDocument,
}: Props) {
  const [question, setQuestion] = useState('');
  const [confirmingClear, setConfirmingClear] = useState(false);
  const [highlightedTurn, setHighlightedTurn] = useState<string | null>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const bottomRef = useRef<HTMLDivElement>(null);
  const turnRefs = useRef(new Map<string, HTMLLIElement>());

  const turnCount = messages.filter(m => m.role === 'user').length;

  // Keep the newest exchange in view when messages arrive or a question is pending/fails.
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ block: 'end' });
  }, [messages.length, pending, failed]);

  // Jump to a turn selected from the History outline.
  useEffect(() => {
    if (!focusRequest) return;
    const el = turnRefs.current.get(focusRequest.turnId);
    if (!el) return;
    el.scrollIntoView({ block: 'start', behavior: 'smooth' });
    el.focus({ preventScroll: true });
    setHighlightedTurn(focusRequest.turnId);
    const t = setTimeout(() => setHighlightedTurn(null), 2000);
    return () => clearTimeout(t);
  }, [focusRequest]);

  const fillInput = (text: string) => {
    setQuestion(text);
    inputRef.current?.focus();
  };

  const submit = () => {
    const trimmed = question.trim();
    if (!trimmed || pending) return;
    onAsk(trimmed);
    setQuestion('');
  };

  const handleClear = async () => {
    await onClearHistory();
    setConfirmingClear(false);
  };

  const isEmpty = messages.length === 0 && !pending && !failed && !loadError;

  return (
    <section
      aria-labelledby="conversation-heading"
      style={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column', borderTop: '1px solid #0f3460' }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '8px',
          padding: '8px 20px',
          background: '#16213e',
          borderBottom: '1px solid #0f3460',
        }}
      >
        <h2 id="conversation-heading" style={{ fontSize: '14px', fontWeight: 600 }}>
          Conversation
          <span style={{ ...metaText, fontWeight: 400, marginLeft: '8px' }}>
            {turnCount} {turnCount === 1 ? 'exchange' : 'exchanges'}
          </span>
        </h2>
        {turnCount > 0 &&
          (confirmingClear ? (
            <div role="group" aria-label="Confirm clearing history" style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
              <span style={{ fontSize: '12px' }}>Delete all {turnCount} exchanges?</span>
              <button type="button" onClick={handleClear} style={{ ...smallButton, background: '#8b2c3c', color: '#fff', borderColor: '#8b2c3c' }}>
                Delete
              </button>
              <button type="button" onClick={() => setConfirmingClear(false)} style={smallButton} autoFocus>
                Cancel
              </button>
            </div>
          ) : (
            <button type="button" onClick={() => setConfirmingClear(true)} style={smallButton}>
              Clear history
            </button>
          ))}
      </div>

      <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', padding: '16px 20px' }}>
        {loadError && (
          <div role="alert" style={{ padding: '10px 14px', marginBottom: '12px', background: '#3a1a2a', border: '1px solid #8b2c3c', borderRadius: '6px', fontSize: '13px' }}>
            Couldn't load conversation history: {loadError}{' '}
            <button type="button" onClick={onReloadHistory} style={smallButton}>
              Try again
            </button>
          </div>
        )}

        {isEmpty && (
          <div style={{ textAlign: 'center', paddingTop: '24px', color: '#a8a8c8', fontSize: '13px' }}>
            <p>No questions yet. Ask something about your documents — follow-up questions can build on earlier ones.</p>
            <ul style={{ listStyle: 'none', marginTop: '12px', display: 'flex', flexWrap: 'wrap', gap: '8px', justifyContent: 'center' }}>
              {EXAMPLE_QUESTIONS.map(q => (
                <li key={q}>
                  <button type="button" onClick={() => fillInput(q)} style={{ ...smallButton, fontSize: '12px', padding: '5px 12px' }}>
                    {q}
                  </button>
                </li>
              ))}
            </ul>
          </div>
        )}

        <ol aria-label="Questions and answers" style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {messages.map(m => {
            const highlighted = highlightedTurn === m.turnId;
            if (m.role === 'user') {
              return (
                <li
                  key={m.id}
                  ref={el => {
                    if (el) turnRefs.current.set(m.turnId, el);
                    else turnRefs.current.delete(m.turnId);
                  }}
                  tabIndex={-1}
                  aria-label={`You asked, ${formatTimestamp(m.timestamp)}`}
                  style={{ display: 'flex', flexDirection: 'column', marginTop: '8px', scrollMarginTop: '8px', borderRadius: '10px' }}
                >
                  <article style={bubble('user', highlighted)}>
                    <header style={{ display: 'flex', justifyContent: 'space-between', gap: '12px', marginBottom: '4px' }}>
                      <span style={{ fontSize: '11px', fontWeight: 600, color: '#e8dcff' }}>You</span>
                      <Timestamp iso={m.timestamp} />
                    </header>
                    <p style={messageText}>{m.content}</p>
                    <div style={{ marginTop: '6px', textAlign: 'right' }}>
                      <button type="button" onClick={() => fillInput(m.content)} style={{ ...smallButton, color: '#e8dcff', borderColor: '#7a5bb5' }}>
                        Edit &amp; ask again
                      </button>
                    </div>
                  </article>
                </li>
              );
            }
            const confidence = m.confidence !== undefined ? Math.round(m.confidence * 100) : null;
            return (
              <li key={m.id} aria-label={`Assistant answered, ${formatTimestamp(m.timestamp)}`} style={{ display: 'flex', flexDirection: 'column' }}>
                <article style={bubble('assistant', highlighted)}>
                  <header style={{ display: 'flex', justifyContent: 'space-between', gap: '12px', marginBottom: '4px' }}>
                    <span style={{ fontSize: '11px', fontWeight: 600, color: '#9d7fe0' }}>Assistant</span>
                    <Timestamp iso={m.timestamp} />
                  </header>
                  <p style={messageText}>{m.content}</p>
                  {m.usedConversationContext && (
                    <p style={{ ...metaText, marginTop: '6px', fontStyle: 'italic' }}>Interpreted as a follow-up to your previous question.</p>
                  )}
                  <CitationList citations={m.citations ?? []} isDocumentAvailable={isDocumentAvailable} onOpenDocument={onOpenDocument} />
                  <footer style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '8px', marginTop: '8px' }}>
                    <span style={metaText}>{confidence !== null ? `Confidence ${confidence}%` : ''}</span>
                    <CopyButton text={m.content} />
                  </footer>
                </article>
              </li>
            );
          })}

          {(pending || failed) && (
            <li style={{ display: 'flex', flexDirection: 'column', gap: '10px', marginTop: '8px' }}>
              <article style={{ ...bubble('user', false), opacity: failed ? 0.7 : 1 }}>
                <header style={{ display: 'flex', justifyContent: 'space-between', gap: '12px', marginBottom: '4px' }}>
                  <span style={{ fontSize: '11px', fontWeight: 600, color: '#e8dcff' }}>You</span>
                  <Timestamp iso={(pending ?? failed)!.askedAt} />
                </header>
                <p style={messageText}>{(pending ?? failed)!.question}</p>
              </article>
              {pending ? (
                <div role="status" style={{ ...bubble('assistant', false), color: '#a8a8c8', fontSize: '13px', fontStyle: 'italic' }}>
                  Searching your documents…
                </div>
              ) : (
                <div role="alert" style={{ ...bubble('assistant', false), background: '#3a1a2a', borderColor: '#8b2c3c', fontSize: '13px' }}>
                  <p>Couldn't get an answer: {failed!.error}</p>
                  <div style={{ display: 'flex', gap: '6px', marginTop: '8px' }}>
                    <button type="button" onClick={onRetry} style={{ ...smallButton, color: '#fff' }}>
                      Retry
                    </button>
                    <button type="button" onClick={onDismissError} style={smallButton}>
                      Dismiss
                    </button>
                  </div>
                </div>
              )}
            </li>
          )}
        </ol>
        <div ref={bottomRef} />
      </div>

      <form
        onSubmit={e => {
          e.preventDefault();
          submit();
        }}
        style={{ display: 'flex', alignItems: 'flex-end', padding: '12px 20px', borderTop: '1px solid #0f3460', background: '#16213e' }}
      >
        <label htmlFor="question-input" className="sr-only">
          Ask a question about your documents
        </label>
        <textarea
          id="question-input"
          ref={inputRef}
          value={question}
          rows={2}
          onChange={e => setQuestion(e.target.value)}
          onKeyDown={e => {
            if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
              e.preventDefault();
              submit();
            }
          }}
          placeholder={turnCount > 0 ? 'Ask a follow-up question…' : 'Ask a question about your documents…'}
          aria-describedby="question-hint"
          style={{
            flex: 1,
            resize: 'none',
            padding: '10px 14px',
            background: '#1a1a2e',
            color: '#e0e0e0',
            border: '1px solid #0f3460',
            borderRadius: '6px',
            fontSize: '14px',
            fontFamily: 'inherit',
            lineHeight: 1.4,
          }}
        />
        <span id="question-hint" className="sr-only">
          Press Enter to send, Shift+Enter for a new line.
        </span>
        <button
          type="submit"
          disabled={!question.trim() || pending !== null}
          style={{
            marginLeft: '10px',
            padding: '10px 20px',
            background: '#533483',
            color: '#fff',
            border: 'none',
            borderRadius: '6px',
            cursor: !question.trim() || pending ? 'not-allowed' : 'pointer',
            opacity: !question.trim() || pending ? 0.6 : 1,
            fontSize: '14px',
            fontWeight: 500,
          }}
        >
          {pending ? 'Asking…' : 'Ask'}
        </button>
      </form>
    </section>
  );
}
import { Citation } from '../../shared/types';

interface Props {
  citations: Citation[];
  /** Returns false when the cited document no longer exists. */
  isDocumentAvailable: (documentId: string) => boolean;
  onOpenDocument: (documentId: string) => void;
}

const PREVIEW_LENGTH = 90;

/** Sources for one answer. Each citation expands (native <details>) to show the full excerpt. */
export function CitationList({ citations, isDocumentAvailable, onOpenDocument }: Props) {
  if (citations.length === 0) {
    return (
      <p style={{ marginTop: '10px', fontSize: '12px', color: '#a8a8c8', fontStyle: 'italic' }}>
        No sources cited — this answer is not grounded in your documents.
      </p>
    );
  }

  return (
    <div style={{ marginTop: '10px' }}>
      <h4 style={{ fontSize: '11px', fontWeight: 600, color: '#a8a8c8', textTransform: 'uppercase', letterSpacing: '0.04em' }}>
        Sources ({citations.length})
      </h4>
      <ol style={{ listStyle: 'none', marginTop: '4px' }}>
        {citations.map((c, i) => {
          const available = isDocumentAvailable(c.documentId);
          const preview = c.excerpt.length > PREVIEW_LENGTH ? `${c.excerpt.slice(0, PREVIEW_LENGTH).trimEnd()}…` : c.excerpt;
          return (
            <li key={`${c.documentId}-${c.chunkIndex}-${i}`} style={{ marginTop: '4px' }}>
              <details style={{ borderLeft: '2px solid #533483', paddingLeft: '8px', fontSize: '12px', color: '#c0c0dd' }}>
                <summary style={{ cursor: 'pointer', lineHeight: 1.5 }}>
                  <span style={{ fontWeight: 600, color: '#e0e0e0' }}>[{i + 1}] {c.documentTitle}</span>
                  <span style={{ color: '#a8a8c8' }}> · chunk {c.chunkIndex}</span>
                  <span style={{ display: 'block', color: '#a8a8c8' }}>{preview}</span>
                </summary>
                <blockquote
                  style={{
                    margin: '6px 0',
                    padding: '8px 10px',
                    background: '#14142e',
                    borderRadius: '4px',
                    whiteSpace: 'pre-wrap',
                    overflowWrap: 'anywhere',
                    lineHeight: 1.5,
                  }}
                >
                  {c.excerpt}
                </blockquote>
                <button
                  type="button"
                  onClick={() => onOpenDocument(c.documentId)}
                  disabled={!available}
                  style={{
                    padding: '3px 10px',
                    background: available ? '#0f3460' : 'transparent',
                    color: available ? '#e0e0e0' : '#a8a8c8',
                    border: '1px solid #1a1a4e',
                    borderRadius: '3px',
                    cursor: available ? 'pointer' : 'not-allowed',
                    fontSize: '11px',
                    marginBottom: '4px',
                  }}
                >
                  {available ? 'Open document' : 'Document no longer available'}
                </button>
              </details>
            </li>
          );
        })}
      </ol>
    </div>
  );
}
import { ConversationMessage } from '../../shared/types';
import { formatFullTimestamp, formatTimestamp } from '../utils/format';

interface Props {
  messages: ConversationMessage[];
  onSelectTurn: (turnId: string) => void;
}

/** Outline of past questions in the sidebar; selecting one jumps to it in the conversation. */
export function ConversationHistory({ messages, onSelectTurn }: Props) {
  const questions = messages.filter(m => m.role === 'user');

  if (questions.length === 0) {
    return (
      <p style={{ padding: '20px', color: '#a8a8c8', textAlign: 'center', fontSize: '13px' }}>
        No conversation history yet. Ask a question to get started.
      </p>
    );
  }

  return (
    <nav aria-label="Conversation history" style={{ flex: 1, overflowY: 'auto' }}>
      <ol style={{ listStyle: 'none' }}>
        {questions.map(q => (
          <li key={q.id}>
            <button
              type="button"
              onClick={() => onSelectTurn(q.turnId)}
              title={q.content}
              style={{
                display: 'block',
                width: '100%',
                textAlign: 'left',
                padding: '10px 16px',
                background: 'transparent',
                color: '#e0e0e0',
                border: 'none',
                borderBottom: '1px solid #0f3460',
                cursor: 'pointer',
              }}
            >
              <span
                style={{
                  display: '-webkit-box',
                  WebkitLineClamp: 2,
                  WebkitBoxOrient: 'vertical',
                  overflow: 'hidden',
                  fontSize: '13px',
                  overflowWrap: 'anywhere',
                }}
              >
                {q.content}
              </span>
              <time dateTime={q.timestamp} title={formatFullTimestamp(q.timestamp)} style={{ display: 'block', fontSize: '11px', color: '#a8a8c8', marginTop: '2px' }}>
                {formatTimestamp(q.timestamp)}
              </time>
            </button>
          </li>
        ))}
      </ol>
    </nav>
  );
}
/** Display-only formatting helpers for the renderer. */

const timeOpts: Intl.DateTimeFormatOptions = { hour: 'numeric', minute: '2-digit' };

function isSameDay(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

/** Human-readable relative timestamp: "Today, 2:05 PM", "Yesterday, …", "Nov 3, …", "Nov 3, 2025, …". */
export function formatTimestamp(iso: string, now: Date = new Date()): string {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return 'Unknown time';
  const time = date.toLocaleTimeString(undefined, timeOpts);
  if (isSameDay(date, now)) return `Today, ${time}`;
  const yesterday = new Date(now);
  yesterday.setDate(now.getDate() - 1);
  if (isSameDay(date, yesterday)) return `Yesterday, ${time}`;
  const day = date.toLocaleDateString(undefined, {
    month: 'short',
    day: 'numeric',
    ...(date.getFullYear() === now.getFullYear() ? {} : { year: 'numeric' }),
  });
  return `${day}, ${time}`;
}

/** Full timestamp for tooltips. */
export function formatFullTimestamp(iso: string): string {
  const date = new Date(iso);
  return Number.isNaN(date.getTime()) ? 'Unknown time' : date.toLocaleString();
}

/** Strip Electron's "Error invoking remote method 'x': Error: " prefix from IPC errors. */
export function describeError(err: unknown): string {
  const raw = err instanceof Error ? err.message : String(err);
  return raw.replace(/^Error invoking remote method '[^']+':\s*(Error:\s*)?/, '') || 'Unknown error';
}

