// Independent judge probe. Runs the built app against a temp userData dir.
const { app, BrowserWindow, ipcMain } = require('electron');
const fs = require('fs');
const os = require('os');
const path = require('path');

const root = path.resolve(__dirname, '..');
const out = path.join(root, 'judge-shots');
fs.mkdirSync(out, { recursive: true });
const phase = process.env.P || 'A';
const userData = process.env.UD || fs.mkdtempSync(path.join(os.tmpdir(), 'kb-judge-'));
app.setPath('userData', userData);
const dataDir = path.join(userData, 'knowledge-base-data');

if (phase === 'C') {
  fs.mkdirSync(dataDir, { recursive: true });
  fs.writeFileSync(path.join(dataDir, 'qa-history.json'), '{ not json');
}
if (phase === 'D') {
  // Legacy entries without id/askedAt + entry missing citations + very long answer
  fs.mkdirSync(dataDir, { recursive: true });
  const long = 'Lorem ipsum dolor sit amet '.repeat(200) + 'END_OF_LONG_ANSWER';
  fs.writeFileSync(path.join(dataDir, 'qa-history.json'), JSON.stringify([
    { question: 'legacy q1', response: { answer: 'legacy a1', citations: [], confidence: 0.3, timestamp: '2025-03-01T10:00:00Z' } },
    { question: 'legacy q2 with a superlongwordwithoutanyspaces'.padEnd(400, 'x'), response: { answer: long, confidence: 0.85, timestamp: new Date(Date.now() - 86400000).toISOString() } },
  ]));
}

const log = (k, v) => console.log(`R ${k}: ${typeof v === 'string' ? v : JSON.stringify(v)}`);
const sleep = ms => new Promise(r => setTimeout(r, ms));
async function waitFor(wc, expr, t = 8000) { const s = Date.now(); while (Date.now() - s < t) { if (await wc.executeJavaScript(`Boolean(${expr})`)) return true; await sleep(100); } return false; }
async function shot(win, n) { fs.writeFileSync(path.join(out, n), (await win.webContents.capturePage()).toPNG()); }
function key(wc, keyCode, mods = []) { wc.sendInputEvent({ type: 'keyDown', keyCode, modifiers: mods }); if (keyCode === 'Enter' || keyCode.length === 1) wc.sendInputEvent({ type: 'char', keyCode: keyCode === 'Enter' ? '\r' : keyCode, modifiers: mods }); wc.sendInputEvent({ type: 'keyUp', keyCode, modifiers: mods }); }
const active = `(() => { const a = document.activeElement; return a.tagName + '|' + (a.id || a.getAttribute('aria-label') || a.textContent.slice(0,40)); })()`;
const A = `document.querySelectorAll('li[aria-label^="Assistant answered"]').length`;

async function ask(wc, q, n) {
  await wc.executeJavaScript(`document.getElementById('question-input').focus()`);
  wc.insertText(q); await sleep(30); key(wc, 'Enter');
  return waitFor(wc, `${A} === ${n}`);
}

async function phaseA(win) {
  const wc = win.webContents;
  // 1. No docs indexed: answer without citations
  await ask(wc, 'What is the architecture?', 1);
  log('no-docs answer', await wc.executeJavaScript(`document.querySelector('li[aria-label^="Assistant answered"]').innerText`));
  await shot(win, 'A1-no-citations.png');
  // Import & index
  const samples = path.join(root, 'data', 'sample-documents');
  for (const f of fs.readdirSync(samples)) await wc.executeJavaScript(`window.knowledgeBase.documents.import(${JSON.stringify(path.join(samples, f))})`);
  await wc.executeJavaScript(`window.knowledgeBase.indexing.start()`);
  await wc.executeJavaScript(`[...document.querySelectorAll('button')].find(b => b.textContent === 'Refresh').click()`);
  await sleep(300);
  // Shift+Enter newline
  await wc.executeJavaScript(`document.getElementById('question-input').focus()`);
  wc.insertText('line one'); key(wc, 'Enter', ['shift']); wc.insertText('line two'); await sleep(100);
  log('shift-enter value', await wc.executeJavaScript(`document.getElementById('question-input').value`));
  key(wc, 'Enter');
  await waitFor(wc, `${A} === 2`);
  log('multiline q rendered', await wc.executeJavaScript(`[...document.querySelectorAll('li[aria-label^="You asked"] article > p')].map(p=>p.textContent)`));
  // Many turns
  const qs = ['How does retrieval work?', 'And what about chunks?', 'Tell me more', 'What was decided in the meeting?', 'How are documents imported?'];
  let n = 2;
  for (let i = 0; i < 4; i++) for (const q of qs) { n++; if (!(await ask(wc, q, n))) log('ask timeout', q); }
  log('turn count', await wc.executeJavaScript(A));
  log('header count text', await wc.executeJavaScript(`document.getElementById('conversation-heading').textContent`));
  log('scrolled to bottom', await wc.executeJavaScript(`(() => { const s = document.querySelector('ol[aria-label="Questions and answers"]').parentElement; return [s.scrollTop + s.clientHeight, s.scrollHeight]; })()`));
  log('timestamps sample', await wc.executeJavaScript(`[...document.querySelectorAll('ol[aria-label="Questions and answers"] time')].slice(0,2).map(t => t.textContent + ' / ' + t.title)`));
  log('usedContext flags', await wc.executeJavaScript(`[...document.querySelectorAll('li[aria-label^="Assistant answered"]')].slice(2,7).map(l => l.innerText.includes('Interpreted as a follow-up'))`));
  log('answers 3-7', await wc.executeJavaScript(`[...document.querySelectorAll('li[aria-label^="Assistant answered"] article > p:first-of-type')].slice(2,7).map(p => p.textContent.slice(0,160))`));
  await shot(win, 'A2-many-turns.png');
  // Citation excerpt vs full chunk
  const exc = await wc.executeJavaScript(`[...document.querySelectorAll('details blockquote')].map(b => b.textContent.length)`);
  log('citation excerpt lengths (max 200?)', [Math.min(...exc), Math.max(...exc)]);
  // Keyboard: Tab through first assistant bubble controls
  await wc.executeJavaScript(`document.getElementById('question-input').focus()`);
  const seq = [];
  for (let i = 0; i < 6; i++) { key(wc, 'Tab', ['shift']); await sleep(60); seq.push(await wc.executeJavaScript(active)); }
  log('shift-tab sequence from input', seq);
  // Keyboard open details: focus last summary, press Enter
  await wc.executeJavaScript(`[...document.querySelectorAll('summary')].pop().focus()`);
  key(wc, 'Enter'); await sleep(150);
  log('Enter on summary opens details', await wc.executeJavaScript(`[...document.querySelectorAll('details')].pop().open`));
  key(wc, 'Tab'); await sleep(60);
  log('after Tab focus', await wc.executeJavaScript(active));
  await shot(win, 'A3-citation-open.png');
  // Delete a cited document -> button state
  const docs = await wc.executeJavaScript(`window.knowledgeBase.documents.list()`);
  const lastCitedTitle = await wc.executeJavaScript(`[...document.querySelectorAll('details summary span')].pop().textContent`);
  const d = docs.find(x => lastCitedTitle.includes(x.title));
  if (d) {
    await wc.executeJavaScript(`window.knowledgeBase.documents.delete(${JSON.stringify(d.id)})`);
    await wc.executeJavaScript(`[...document.querySelectorAll('button')].find(b => b.textContent === 'Refresh').click()`);
    await sleep(300);
    log('deleted doc citation button', await wc.executeJavaScript(`[...document.querySelectorAll('details')].pop().querySelector('button').textContent`));
    // asking now cites deleted doc?
    n++; await ask(wc, 'How does retrieval work?', n);
    log('post-delete citation titles', await wc.executeJavaScript(`[...document.querySelectorAll('li[aria-label^="Assistant answered"]')].pop().querySelectorAll('summary span:first-child').length ? [...[...document.querySelectorAll('li[aria-label^="Assistant answered"]')].pop().querySelectorAll('summary span:first-child')].map(s=>s.textContent) : []`));
  }
  // Pending: double submit
  await wc.executeJavaScript(`document.getElementById('question-input').focus()`);
  wc.insertText('first pending'); key(wc, 'Enter'); await sleep(20);
  log('submit disabled while pending', await wc.executeJavaScript(`document.querySelector('form button[type=submit]').disabled + ' / ' + document.querySelector('form button[type=submit]').textContent`));
  wc.insertText('typed during pending'); key(wc, 'Enter'); await sleep(20);
  log('input during pending kept', await wc.executeJavaScript(`document.getElementById('question-input').value`));
  await shot(win, 'A4-pending.png');
  n++; await waitFor(wc, `${A} === ${n}`);
  await sleep(700);
  log('turns after double submit (expect +1)', await wc.executeJavaScript(A) + ' expected ' + n);
  // Clear-history failure
  ipcMain.removeHandler('qa:clear-history');
  ipcMain.handle('qa:clear-history', async () => { throw new Error('disk full'); });
  await wc.executeJavaScript(`[...document.querySelectorAll('button')].find(b => b.textContent === 'Clear history').click()`);
  await sleep(100);
  log('Escape cancels confirm?', 'testing'); key(wc, 'Escape'); await sleep(100);
  log('confirm still visible after Escape', await wc.executeJavaScript(`!!document.querySelector('[aria-label="Confirm clearing history"]')`));
  await wc.executeJavaScript(`[...document.querySelectorAll('button')].find(b => b.textContent === 'Delete')?.click()`);
  await sleep(500);
  log('clear failure visible to user', await wc.executeJavaScript(`[...document.querySelectorAll('[role=alert]')].map(a=>a.textContent)`));
  log('turns after failed clear', await wc.executeJavaScript(A));
  // Contrast of inactive tab
  log('inactive tab color', await wc.executeJavaScript(`(() => { const b=[...document.querySelectorAll('button[aria-pressed=false]')][0]; return b.textContent + ' ' + getComputedStyle(b).color; })()`));
  await wc.executeJavaScript(`[...document.querySelectorAll('button')].find(b => b.textContent.startsWith('History')).click()`);
  await sleep(200);
  await shot(win, 'A5-history-tab.png');
}

async function phaseC(win) {
  const wc = win.webContents; await sleep(800);
  log('corrupt history UI', await wc.executeJavaScript(`document.querySelector('ol[aria-label="Questions and answers"]').parentElement.innerText.slice(0,300)`));
  await shot(win, 'C-corrupt.png');
  await ask(wc, 'new question after corrupt', 1);
  log('after asking with corrupt file, turns', await wc.executeJavaScript(A));
}

async function phaseD(win) {
  const wc = win.webContents; await sleep(800);
  log('legacy turns', await wc.executeJavaScript(A));
  log('legacy timestamps', await wc.executeJavaScript(`[...document.querySelectorAll('ol[aria-label="Questions and answers"] time')].map(t=>t.textContent)`));
  log('long answer full', await wc.executeJavaScript(`[...document.querySelectorAll('article p')].some(p => p.textContent.endsWith('END_OF_LONG_ANSWER'))`));
  log('horizontal overflow', await wc.executeJavaScript(`(() => { const s = document.querySelector('ol[aria-label="Questions and answers"]').parentElement; return [s.scrollWidth, s.clientWidth]; })()`));
  log('missing citations answer', await wc.executeJavaScript(`[...document.querySelectorAll('li[aria-label^="Assistant answered"]')][1].innerText.includes('No sources cited')`));
  await wc.executeJavaScript(`document.querySelector('li[aria-label^="You asked"]').scrollIntoView()`);
  await shot(win, 'D-legacy-long.png');
}

app.whenReady().then(async () => {
  require(path.join(root, 'dist', 'main', 'main.js'));
  let win; for (let i = 0; i < 50 && !win; i++) { await sleep(100); win = BrowserWindow.getAllWindows()[0]; }
  if (win.webContents.isLoading()) await new Promise(r => win.webContents.once('did-finish-load', r));
  win.webContents.on('console-message', (_e, lvl, msg) => { if (lvl >= 2) console.log('CONSOLE', msg); });
  await sleep(300);
  try { await ({ A: phaseA, C: phaseC, D: phaseD })[phase](win); } catch (e) { log('EXCEPTION', String(e.stack)); }
  app.exit(0);
});

