// Independent judge probe. Runs the built app against a temp userData dir.
const { app, BrowserWindow, ipcMain } = require('electron');
const fs = require('fs');
const os = require('os');
const path = require('path');

const root = path.resolve(__dirname, '..');
const out = path.join(root, 'judge-shots');
fs.mkdirSync(out, { recursive: true });
const phase = process.env.P || 'A';
const userData = process.env.UD || fs.mkdtempSync(path.join(os.tmpdir(), 'kb-judge-'));
app.setPath('userData', userData);
const dataDir = path.join(userData, 'knowledge-base-data');

if (phase === 'C') {
  fs.mkdirSync(dataDir, { recursive: true });
  fs.writeFileSync(path.join(dataDir, 'qa-history.json'), '{ not json');
}
if (phase === 'D') {
  // Legacy entries without id/askedAt + entry missing citations + very long answer
  fs.mkdirSync(dataDir, { recursive: true });
  const long = 'Lorem ipsum dolor sit amet '.repeat(200) + 'END_OF_LONG_ANSWER';
  fs.writeFileSync(path.join(dataDir, 'qa-history.json'), JSON.stringify([
    { question: 'legacy q1', response: { answer: 'legacy a1', citations: [], confidence: 0.3, timestamp: '2025-03-01T10:00:00Z' } },
    { question: 'legacy q2 with a superlongwordwithoutanyspaces'.padEnd(400, 'x'), response: { answer: long, confidence: 0.85, timestamp: new Date(Date.now() - 86400000).toISOString() } },
  ]));
}

const log = (k, v) => console.log(`R ${k}: ${typeof v === 'string' ? v : JSON.stringify(v)}`);
const sleep = ms => new Promise(r => setTimeout(r, ms));
async function waitFor(wc, expr, t = 8000) { const s = Date.now(); while (Date.now() - s < t) { if (await wc.executeJavaScript(`Boolean(${expr})`)) return true; await sleep(100); } return false; }
async function shot(win, n) { fs.writeFileSync(path.join(out, n), (await win.webContents.capturePage()).toPNG()); }
function key(wc, keyCode, mods = []) { wc.sendInputEvent({ type: 'keyDown', keyCode, modifiers: mods }); if (keyCode === 'Enter' || keyCode.length === 1) wc.sendInputEvent({ type: 'char', keyCode: keyCode === 'Enter' ? '\r' : keyCode, modifiers: mods }); wc.sendInputEvent({ type: 'keyUp', keyCode, modifiers: mods }); }
const active = `(() => { const a = document.activeElement; return a.tagName + '|' + (a.id || a.getAttribute('aria-label') || a.textContent.slice(0,40)); })()`;
const A = `document.querySelectorAll('li[aria-label^="Assistant answered"]').length`;

async function ask(wc, q, n) {
  await wc.executeJavaScript(`document.getElementById('question-input').focus()`);
  wc.insertText(q); await sleep(30); key(wc, 'Enter');
  return waitFor(wc, `${A} === ${n}`);
}

