const { app, BrowserWindow } = require('electron');
const fs = require('fs'), os = require('os'), path = require('path');
const root = path.resolve(__dirname, '..');
const ud = fs.mkdtempSync(path.join(os.tmpdir(), 'kb-jump-')); app.setPath('userData', ud);
const dd = path.join(ud, 'knowledge-base-data'); fs.mkdirSync(dd, { recursive: true });
const now = Date.now();
fs.writeFileSync(path.join(dd, 'qa-history.json'), JSON.stringify(Array.from({ length: 15 }, (_, i) => ({ id: 't' + i, question: 'Question number ' + i, askedAt: new Date(now - 60000 * (15 - i)).toISOString(), response: { answer: 'Answer '.repeat(60) + i, citations: [], confidence: 0.3, timestamp: new Date(now - 60000 * (15 - i) + 500).toISOString() } }))));
const sleep = ms => new Promise(r => setTimeout(r, ms));
app.whenReady().then(async () => {
  require(path.join(root, 'dist', 'main', 'main.js'));
  let win; for (let i = 0; i < 50 && !win; i++) { await sleep(100); win = BrowserWindow.getAllWindows()[0]; }
  if (win.webContents.isLoading()) await new Promise(r => win.webContents.once('did-finish-load', r));
  await sleep(800); const wc = win.webContents;
  const geo = `JSON.stringify({rootTop: document.getElementById('root').scrollTop, htmlTop: document.documentElement.scrollTop, bodyTop: document.body.scrollTop, headerY: document.querySelector('header').getBoundingClientRect().top, formBottom: document.querySelector('form').getBoundingClientRect().bottom, vh: innerHeight})`;
  console.log('R before', await wc.executeJavaScript(geo));
  await wc.executeJavaScript(`[...document.querySelectorAll('button')].find(b => b.textContent.startsWith('History')).click()`); await sleep(200);
  for (const idx of [0, 7]) {
    await wc.executeJavaScript(`document.querySelectorAll('nav[aria-label="Conversation history"] button')[${idx}].click()`); await sleep(1200);
    console.log('R after jump to', idx, await wc.executeJavaScript(geo), await wc.executeJavaScript(`document.activeElement.getAttribute('aria-label')`));
    fs.writeFileSync(path.join(root, 'judge-shots', 'J' + idx + '.png'), (await win.webContents.capturePage()).toPNG());
  }
  app.exit(0);
});
EOF
